const body = $input.item.json.body;
const fileId = body.fileId;
const userId = body.userId;
const sharedWith = body.sharedWith || [];
const fileName = body.fileName || 'unknown';
const filePath = body.fileUrl.replace('file://uploads/', '/app/uploads/');

if (!fileId || !filePath || !userId) {
  throw new Error('fileId, filePath, and userId are required');
}

return { fileId, userId, sharedWith, fileName, filePath };

// Check if PDF has extractable text using pdftotext
const { execSync } = require('child_process');
const fs = require('fs');

const filePath = $('Parse File Info').item.json.filePath;
const ext = filePath.split('.').pop().toLowerCase();

let hasText = false;
let isImage = false;

if (ext === 'pdf') {
  try {
    const text = execSync(`pdftotext "${filePath}" - 2>/dev/null`).toString().trim();
    // If extracted text is very short relative to pages, likely scanned
    const pageCount = parseInt(execSync(`pdfinfo "${filePath}" 2>/dev/null | grep Pages | awk '{print $2}'`).toString().trim()) || 1;
    hasText = text.length > (pageCount * 50); // at least 50 chars per page
  } catch(e) {
    hasText = false;
  }
} else if (['png','jpg','jpeg','gif','bmp','tiff','tif','webp'].includes(ext)) {
  isImage = true;
  hasText = false;
} else {
  // txt, doc, etc - assume has text
  hasText = true;
}

return {
  ...($('Parse File Info').item.json),
  hasText,
  isImage,
  fileExt: ext
};

// Convert PDF pages to images using pdftoppm, or pass image file directly
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const info = $('Parse File Info').item.json;
const filePath = info.filePath;
const ext = $('Check PDF Type').item.json.fileExt;
const tmpDir = `/tmp/ocr_${info.fileId}`;

execSync(`mkdir -p ${tmpDir}`);

let imageFiles = [];

if (ext === 'pdf') {
  // Convert PDF to PNG images (one per page)
  execSync(`pdftoppm -png -r 300 "${filePath}" "${tmpDir}/page"`);
  imageFiles = fs.readdirSync(tmpDir)
    .filter(f => f.endsWith('.png'))
    .sort()
    .map(f => path.join(tmpDir, f));
} else {
  // Single image file
  imageFiles = [filePath];
}

const items = imageFiles.map((imgPath, i) => ({
  json: {
    imagePath: imgPath,
    pageNum: i + 1,
    totalPages: imageFiles.length,
    tmpDir,
    ...info
  }
}));

return items;

