// Combine all OCR pages into chunks for embedding
const { execSync } = require('child_process');
const items = $input.all();
const info = $('Parse File Info').item.json;

// Combine all page texts
const fullText = items.map((item, i) => {
  const text = item.json.message?.content || '';
  return `--- Page ${i+1} ---\n${text}`;
}).join('\n\n');

// Cleanup tmp dir
try {
  const tmpDir = $('PDF to Images').first().json.tmpDir;
  if (tmpDir) execSync(`rm -rf ${tmpDir}`);
} catch(e) {}

// Split into chunks (~500 chars with overlap)
const chunkSize = 500;
const overlap = 50;
const chunks = [];
for (let i = 0; i < fullText.length; i += chunkSize - overlap) {
  chunks.push(fullText.slice(i, i + chunkSize));
}

return chunks.map((text, i) => ({
  json: {
    text,
    metadata: {
      fileId: info.fileId,
      userId: info.userId,
      sharedWith: info.sharedWith,
      fileName: info.fileName,
      uploadedAt: new Date().toISOString(),
      chunkIndex: i,
      source: 'ocr'
    }
  }
}));

const chunks = $input.all();
const info = $('Parse File Info').item.json;
return {
  success: true,
  message: 'File embedded successfully',
  fileId: info.fileId,
  fileName: info.fileName,
  chunks: chunks.length
};
